<?php
/**
 * Peakopay — Configuration container.
 *
 * Layered configuration (later wins for the keys it defines):
 *   1. Built-in defaults
 *   2. .env file (optional — see .env.example; ops-level switches always win)
 *   3. config/config.php (generated by the web installer — authoritative
 *      after installation for db / app_key / base_url)
 *
 * The config file lives OUTSIDE the routed web root paths and is denied by
 * .htaccess. It contains secrets — never commit it, never serve it.
 */
declare(strict_types=1);

final class Config
{
    private static array $data = [];
    private static bool $loaded = false;

    /** Raw values parsed from .env (KEY => value), for the installer prefill. */
    private static array $envRaw = [];

    public const DEFAULTS = [
        'app_key'  => '',      // 64 hex chars (32 bytes) — generated at install time
        'base_url' => '',      // e.g. https://pay.example.com (no trailing slash)
        'debug'    => false,
        'app_env'  => 'production',
        'session_secure'        => false, // force secure session cookies (set via .env)
        'webhook_allowed_hosts' => '',    // comma list; empty = no extra restriction (set via .env)
        'db'       => [
            'host'    => 'localhost',
            'port'    => 3306,
            'name'    => '',
            'user'    => '',
            'pass'    => '',
            'charset' => 'utf8mb4',
        ],
    ];

    public static function load(string $file): void
    {
        self::$data = self::DEFAULTS;

        // 1) .env (optional) — one level above config/
        $envFile = dirname($file, 2) . '/.env';
        self::$envRaw = self::parseEnvFile($envFile);
        self::applyEnv(self::$envRaw);

        // 2) config/config.php (installer) — overrides .env for its own keys
        if (is_file($file)) {
            $loaded = require $file;
            if (is_array($loaded)) {
                self::$data = array_replace_recursive(self::$data, $loaded);
            }
        }

        // 3) ops switches defined in .env always win (they are server-level
        //    policy, not installation data)
        if (self::$envRaw !== []) {
            if (isset(self::$envRaw['SESSION_SECURE'])) {
                self::$data['session_secure'] = self::envBool((string) self::$envRaw['SESSION_SECURE']);
            }
            if (isset(self::$envRaw['WEBHOOK_ALLOWED_HOSTS'])) {
                self::$data['webhook_allowed_hosts'] = trim((string) self::$envRaw['WEBHOOK_ALLOWED_HOSTS']);
            }
            if (isset(self::$envRaw['APP_ENV'])) {
                self::$data['app_env'] = trim((string) self::$envRaw['APP_ENV']);
            }
        }
        self::$loaded = true;
    }

    /** Dot-notation getter: Config::get('db.host'). */
    public static function get(string $key, mixed $default = null): mixed
    {
        $node = self::$data;
        foreach (explode('.', $key) as $part) {
            if (!is_array($node) || !array_key_exists($part, $node)) {
                return $default;
            }
            $node = $node[$part];
        }
        return $node;
    }

    public static function set(string $key, mixed $value): void
    {
        $parts = explode('.', $key);
        $ref = &self::$data;
        foreach ($parts as $p) {
            if (!is_array($ref)) {
                $ref = [];
            }
            $ref = &$ref[$p];
        }
        $ref = $value;
    }

    public static function all(): array
    {
        return self::$data;
    }

    public static function isLoaded(): bool
    {
        return self::$loaded;
    }

    /** Raw .env value (e.g. Config::env('DB_DSN')) — installer prefill. */
    public static function env(string $key): ?string
    {
        return self::$envRaw[$key] ?? null;
    }

    public static function configFile(): string
    {
        return HP_BASE . '/config/config.php';
    }

    public static function exists(): bool
    {
        return is_file(self::configFile());
    }

    /** Writes the config file (installer only). Throws when not writable. */
    public static function write(array $overrides = []): void
    {
        $data = array_replace_recursive(self::$data, $overrides);
        self::$data = $data; // keep memory in sync (a re-require can serve a stale OPcache entry)
        $file = self::configFile();
        $dir  = dirname($file);
        if (!is_dir($dir) && !@mkdir($dir, 0750, true)) {
            throw new RuntimeException("Cannot create directory: {$dir}");
        }
        $php = "<?php\n"
             . "/**\n * Peakopay configuration — generated by the web installer.\n"
             . " * This file contains secrets; it lives outside the routed web paths (backend/config)\n"
             . " * and is denied by .htaccess.\n"
             . " * Generated: " . gmdate('Y-m-d H:i:s') . " UTC\n */\n"
             . 'return ' . var_export($data, true) . ";\n";
        if (@file_put_contents($file, $php, LOCK_EX) === false) {
            throw new RuntimeException("Cannot write config file: {$file} — check directory permissions.");
        }
        clearstatcache(true, $file); // OPcache hosts with validate_timestamps=0 stay stale otherwise
        @chmod($file, 0640);
    }

    /** Public base URL (no trailing slash). Falls back to the current request. */
    public static function baseUrl(): string
    {
        $configured = (string) self::get('base_url', '');
        if ($configured !== '') {
            return rtrim($configured, '/');
        }
        return Http::guessBaseUrl();
    }

    /** Absolute URL for a path inside this app. */
    public static function url(string $path = ''): string
    {
        return self::baseUrl() . '/' . ltrim($path, '/');
    }

    // ------------------------------------------------------------- .env

    /**
     * Minimal .env parser: KEY=VALUE lines, optional single/double quotes,
     * "#" comments, blank lines. No dependency on any extension.
     *
     * @return array<string,string>
     */
    public static function parseEnvFile(string $file): array
    {
        if (!is_file($file) || !is_readable($file)) {
            return [];
        }
        $out = [];
        $lines = file($file, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) ?: [];
        foreach ($lines as $line) {
            $line = trim((string) $line);
            if ($line === '' || str_starts_with($line, '#')) {
                continue;
            }
            $pos = strpos($line, '=');
            if ($pos === false) {
                continue;
            }
            $key = trim(substr($line, 0, $pos));
            $val = trim(substr($line, $pos + 1));
            if ($val !== '' && ($val[0] === '"' || $val[0] === "'") && strlen($val) >= 2 && $val[strlen($val) - 1] === $val[0]) {
                $val = substr($val, 1, -1);
            }
            if ($key !== '') {
                $out[$key] = $val;
            }
        }
        return $out;
    }

    /** Map parsed .env values onto the internal config tree. */
    private static function applyEnv(array $env): void
    {
        if (isset($env['APP_URL']) && (string) $env['APP_URL'] !== '') {
            self::$data['base_url'] = rtrim((string) $env['APP_URL'], '/');
        }
        if (isset($env['APP_KEY']) && (string) $env['APP_KEY'] !== '') {
            self::$data['app_key'] = (string) $env['APP_KEY'];
        }
        if (isset($env['APP_ENV'])) {
            self::$data['debug'] = !in_array(trim((string) $env['APP_ENV']), ['production', 'prod'], true);
        }
        // DB_DSN: mysql:host=localhost;port=3306;dbname=user_x;charset=utf8mb4
        if (isset($env['DB_DSN']) && (string) $env['DB_DSN'] !== '') {
            $dsn = (string) $env['DB_DSN'];
            $colon = strpos($dsn, ':');
            if ($colon !== false && stripos($dsn, 'host=') > $colon) {
                $dsn = substr($dsn, $colon + 1); // strip the "mysql:" scheme prefix
            }
            foreach (explode(';', $dsn) as $part) {
                $kv = explode('=', $part, 2);
                if (count($kv) !== 2) {
                    continue;
                }
                [ $k, $v ] = [ strtolower(trim($kv[0])), trim($kv[1]) ];
                if ($k === 'host') {
                    self::$data['db']['host'] = $v;
                } elseif ($k === 'port') {
                    self::$data['db']['port'] = (int) $v;
                } elseif ($k === 'dbname') {
                    self::$data['db']['name'] = $v;
                } elseif ($k === 'charset') {
                    self::$data['db']['charset'] = $v !== '' ? $v : 'utf8mb4';
                }
            }
        }
        if (isset($env['DB_USER'])) {
            self::$data['db']['user'] = (string) $env['DB_USER'];
        }
        if (isset($env['DB_PASSWORD'])) {
            self::$data['db']['pass'] = (string) $env['DB_PASSWORD'];
        }
    }

    private static function envBool(string $value): bool
    {
        return in_array(strtolower(trim($value)), ['1', 'true', 'yes', 'on'], true);
    }

    /** Test helper — reset the singleton state. */
    public static function reset(): void
    {
        self::$data = self::DEFAULTS;
        self::$envRaw = [];
        self::$loaded = false;
    }
}
